markdown_to_html.code:
function run(args) {
  if (typeof args.markdown !== 'string') {
    throw new Error('Input must be a string of Markdown text.');
  }

  // Simple Markdown to HTML conversion
  let html = args.markdown
    .replace(/# (.*?)\n/g, '<h1>$1</h1>\n')
    .replace(/## (.*?)\n/g, '<h2>$1</h2>\n')
    .replace(/### (.*?)\n/g, '<h3>$1</h3>\n')
    .replace(/#### (.*?)\n/g, '<h4>$1</h4>\n')
    .replace(/##### (.*?)\n/g, '<h5>$1</h5>\n')
    .replace(/###### (.*?)\n/g, '<h6>$1</h6>\n')
    .replace(/\*\*(.*?)\*\*/g, '<strong>$1</strong>')
    .replace(/\*(.*?)\*/g, '<em>$1</em>')
    .replace(/`(.*?)`/g, '<code>$1</code>')
    .replace(/\n\n/g, '</p><p>')
    .replace(/\n/g, '<br>');

  // Wrap in paragraph tags
  html = `<p>${html}</p>`;

  return html;
}

