html_to_text.code:
function run(args) {
  const htmlPath = args.html_path ?? '';
  if (!htmlPath) {
    throw new Error('html_path is required');
  }

  const htmlContent = harness.fs.read(htmlPath);
  if (!htmlContent) {
    throw new Error(`File not found: ${htmlPath}`);
  }

  const parser = new DOMParser();
  const doc = parser.parseFromString(htmlContent, 'text/html');
  const text = doc.body.textContent || '';

  return text.trim();
}

