base64_encode.code:
function run(args) {
  if (args.file_path) {
    if (!args.file_path.endsWith('.txt')) {
      throw new Error("Only .txt files are supported for encoding.");
    }
    const content = harness.fs.read(args.file_path);
    if (!content) {
      throw new Error(`File not found: ${args.file_path}`);
    }
    return btoa(content);
  } else if (args.text) {
    return btoa(args.text);
  } else {
    throw new Error("Either 'file_path' or 'text' must be provided.");
  }
}

